    stopComputer: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Emergency stop has been set; previously dispatched effects are not rolled back. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "stopped";
                    };
                };
            };
            /** @description Revocation requested; the companion must close its browser. Already dispatched effects may require reconciliation. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
    createComputerPairing: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": {
                    /** @enum {integer} */
                    protocol_version?: 1 | 3;
                    run_id?: string;
                    input_id?: string;
                    previous_session?: string;
                    /** @enum {string} */
                    approval_mode?: "ask_every_time" | "scoped_changes" | "full_task";
                };
            };
        };
        responses: {
            /** @description Administrator-only single-use enrollment code, valid for two minutes. Never cache or log. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        code: string;
                        expires_seconds: number;
                        protocol_version: number;
                    };
                };
            };
        };
    };
    listComputerSessions: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Live local computer sessions owned by the requesting administrator. Driver availability is not workflow qualification. Browser clients must not select native sessions. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        sessions: {
                            id: string;
                            origin: string;
                            /** @enum {string} */
                            driver?: "browser" | "windows-uia" | "macos-accessibility" | "linux-atspi";
                            /** @enum {string} */
                            approval_mode: "ask_every_time" | "scoped_changes" | "full_task";
                            /** @description Companion-issued native identity. Protocol 2 binds one window; protocol 3 binds a task desktop, with actual targets separately bound at dispatch. */
                            target?: {
                                id: string;
                                os_session: string;
                                process_generation: string;
                                surface: string;
                                /** @enum {string} */
                                driver: "windows-uia" | "macos-accessibility" | "linux-atspi";
                            };
                            /** Format: date-time */
                            expires_at: string;
                            remaining_actions: number;
                            /** @enum {string} */
                            state?: "ready" | "awaiting_consent" | "in_use" | "finished" | "exhausted";
                            run_id?: string;
                            input_id?: string;
                            desktop?: {
                                workspace: string;
                                binding: {
                                    actor: string;
                                    task: string;
                                    companion: string;
                                    session: string;
                                    target: {
                                        [key: string]: string;
                                    };
                                };
                            };
                        }[];
                    };
                };
            };
        };
    };
    stopComputerSession: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    session_id: string;
                };
            };
        };
        responses: {
            /** @description This actor's authority for the specified session is revoked. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "revoked";
                    };
                };
            };
            400: components["responses"]["Error"];
            503: components["responses"]["Error"];
        };
    };
    checkComputerModel: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    model: string;
                    /**
                     * @default browser
                     * @enum {string}
                     */
                    driver?: "browser" | "windows-uia" | "macos-accessibility" | "linux-atspi";
                };
            };
        };
        responses: {
            /** @description Completed compatibility check, including a negative result. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ComputerModelCheck"];
                };
            };
            /** @description Runtime unavailable or check timed out; retryable, not proof of incompatibility. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"] & {
                        timings?: components["schemas"]["ComputerModelCheckTimings"];
                    };
                };
            };
        };
    };
